#!/usr/bin/env python3
"""sen0414_lineage_exam_repair_a3 v1_0_0 - records (ONE new register file) the controller's verdict on TK4_Items_B2 (the executor stopped: the merged lists A plus B build no paper; the report is true), the finding on its cause, the counting ruling, and the repair task TK4_Items_A3 (set A rewritten to the design's plan unit by unit) with its control TK4_Items_A3_Verify, both Ready, ranked first. TK4_Items_B2 and its control stay open until the merged lists build.
Usage: sen0414_lineage_exam_repair_a3_v1_0_0.py"""
__version__ = "1.0.0"
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
NS = "http://example.org/sen0414-slides-lineage#"
def blk(t, name):
    i = t.index("\nex:%s a backlog:" % name) + 1; j = t.find("\nex:", i + 1)
    return i, (len(t) if j < 0 else j)
REP = ("RESULT OF THE EXECUTOR of TK4_Items_B2 (real start 2026-11-01T19:09:32Z; commit 034c4dd; recorded as reported) and the controller's own re-runs (log control_itemsb2_run1.log): items_b_v2_0_0.json and items_b_v2_0_0_makeup.json (Q3c 5, Q4c 5, Q5c 2, Q5d 2 points), a provisional side file, builder and check. Merged with set A per list: units 6/7/7/6/4 = 30, points 25/25/25/25/10, no repeated id, validator 0 failures. NOT ACHIEVED, and the report is true: the engine v1_1_0 refuses both merged lists on E03 (units per chapter against the quota; the paper has chapter 3 ten times and chapters 1, 2, 8 once; the make-up 2, 2, 5, 9, 3, 3, 1, 5) and on E09 (cross-chapter 8 and 6 against the minimum 9). The task is therefore NOT Done: its brief required that the two sets together satisfy the engine. The executor stopped and edited nothing committed.")
RULING = ("COUNTING RULING of the lineage agent (2026-11-01), taken from the design v1_2_0 and the engine's own code: (1) the design gives every unit (gap, premise, step, choice) its own chapter; a record of several units lists exactly one chapter per unit, in order, and the engine's cycling of a shorter list is not used; (2) a one-unit choice record counts for the first chapter it lists and is cross-chapter when it lists two or more; the design's nine cross-chapter units are choices (Q1f, Q3f, Q3g, Q4e, Q4f, Q5a to Q5d); (3) the indirect form belongs to the choice records the design marks (six); (4) abbreviation expansion is checked per record because the order of records differs between forms. The engine, the design and the validator do not change.")
FIND = ("Set A was written (TK4_Items_A2, controlled Done) to the validator and the unit counts but without the design's plan for each unit: chapters per unit and which choices are cross-chapter. The briefs r10 to r12 said what a unit and a record are but did not hand the plan unit by unit, and the lineage agent's control of TK4_Items_A2 checked the validator, the counts and the chapter coverage (every chapter present) but not the chapter quotas that the engine enforces, so the shortfall appeared only when the engine saw the merged lists. The engine is right and nothing was weakened.")
REME = ("A repair task TK4_Items_A3 (set A, version 2.1.0, records that follow the design plan unit by unit; brief r13) enters Ready and is ranked first; its control TK4_Items_A3_Verify requires the engine to build the merged lists (every rule E01 to E28 passing). TK4_Items_B2 and TK4_Items_B2_Verify become Done after that, on the controller's own re-run of the merged build. The control of every later item set recomputes the engine's quotas, not only the validator.")
def main():
    src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now(); nowZ = now + "Z"; add = []
    for k in ("TK4_Items_B2", "TK4_Items_B2_Verify", "ST4_Items2"): add.append("ex:%s backlog:hasAuditNote %s .\n" % (k, W.lit(REP + " " + RULING)))
    add.append('ex:Finding_SetAPlan a backlog:RetrospectiveFinding ;\n    rdfs:label "Set A did not follow the design plan unit by unit and the control did not check the quotas"@en ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:relatesToWorkItem ex:ST4_Items2 ; backlog:hasFindingScope backlog:Scope_Methodology ;\n    backlog:hasRootCause %s ;\n    backlog:hasRemedy %s .\n' % (W.lit(FIND), W.lit(REME)))
    size = 2.0
    SPEC = ("Deliverable: the item set A rewritten as 04-assessment/exams/items/items_a_v2_1_0.json (paper list) and items_a_v2_1_0_makeup.json (make-up list), with a provisional side file, a builder and a check, as new files over version 2.0.0; every record follows the design v1_2_0 plan unit by unit (chapter per unit, cross-chapter choices, points, Bloom, asks); merged with set B (version 2.0.0, unchanged) per list the engine v1_1_0 builds a paper with every rule E01 to E28 passing. Executor session SEN0414-EX-items-a3; brief 08-tooling/briefs/exam/r13/BRIEF_TK4_Items_A3.md. Estimated 2.0 hours (an estimate, G120).")
    VER = ("Control by the lineage agent on its own re-runs: the validator on both merged lists (0 failures), the units and points per question, the units per chapter equal to the quota, the cross-chapter and indirect counts, Apply and above and Analyze and above, no identical stem between the lists, and the engine's build of each merged pool with every rule E01 to E28 passing; the commit adds only new files. Estimated 0.5 hours (an estimate, G120).")
    for k, title, typ, text_ in (("TK4_Items_A3", "Item set A, version 2.1.0: records that follow the design plan unit by unit", "Build", SPEC), ("TK4_Items_A3_Verify", "Verify item set A version 2.1.0 on the controller's own engine build", "Verify", VER)):
        isv = typ == "Verify"
        add.append('\nex:%s a backlog:ExecutionTask ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:admittedByOutput ex:Out4_Backlog ; backlog:responsible ex:Executor_ClaudeCodeSession ;\n    backlog:hasInvestmentCategory backlog:%s ; backlog:hasTaskType backlog:TaskType_%s ; backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasState backlog:Ready ;\n%s    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Ranked by its story\'s state; scoring both would double-count." ;\n    backlog:hasAuditNote %s .\n' % (k, W.lit(title), k, W.lit(title), "Cat_Compliance" if isv else "Cat_NewCapability", typ, "    backlog:dependsOn ex:TK4_Items_A3 ;\n" if isv else "", W.lit(text_)))
        add.append('ex:Refine4g_%s a backlog:RefinementEvent ; rdfs:label "Refinement that made %s ready"@en ;\n    backlog:refines ex:%s ; backlog:addressesConcern backlog:Concern_Data ; backlog:refinedAt "%sZ"^^xsd:dateTime ;\n    backlog:refinedBy backlog:Builder ; backlog:groomsForIteration ex:Iter_Ex3 ; backlog:hasWorkKind backlog:WorkKind_Preparation ;\n    backlog:hasRefinementOutcome "Refined from the executor report of TK4_Items_B2 and the controller\'s ruling: the plan per unit is in the brief, the check is named, the estimate is written." .\n' % (k, k, k, now))
        add.append('ex:RC4g_%s a backlog:ReadinessCheck ; rdfs:label "Readiness check of %s"@en ; backlog:checksReadinessOf ex:%s ; backlog:readinessCheckedAt "%sZ"^^xsd:dateTime ;\n    backlog:hasReadinessCriterion ex:RK4g_%s_1, ex:RK4g_%s_2, ex:RK4g_%s_3 .\n' % (k, k, k, now, k, k, k))
        for kx, tx in ((1, "The deliverable, its place and its check are written in the item."), (2, "Every dependency of the item is Done or a task of the same story that precedes it."), (3, "The Owner's statements that bound the item are recorded in the mission and the scope.")):
            add.append('ex:RK4g_%s_%d a backlog:ReadinessCriterion ; rdfs:label %s@en ; backlog:criterionMet true .\n' % (k, kx, W.lit(tx)))
        add.append('ex:Mv4g_%s a backlog:TransitionEvent ; rdfs:label %s@en ; backlog:transitionedItem ex:%s ;\n    backlog:viaTransition backlog:T_Refine ; backlog:transitionedAt "%s"^^xsd:dateTime ; backlog:transitionedBy backlog:Builder ;\n    backlog:hasTransitionNote %s .\n' % (k, W.lit(k + " moved to Ready"), k, nowZ, W.lit("Refined (ex:Refine4g_%s) and ready after the readiness check ex:RC4g_%s; no executor has started." % (k, k))))
        add.append("<%sUrgent_4> backlog:urgentItem <%s%s> .\n" % (NS, NS, k))
    add.append("ex:ST4_Items2 backlog:decomposesInto ex:TK4_Items_A3, ex:TK4_Items_A3_Verify .\nex:Plan4e_ST4_Items2 backlog:producesTask ex:TK4_Items_A3, ex:TK4_Items_A3_Verify .\nex:Iter_Ex3 backlog:hasMember ex:TK4_Items_A3, ex:TK4_Items_A3_Verify .\nex:TK4_Items_B2_Verify backlog:dependsOn ex:TK4_Items_A3_Verify .\n")
    for s2 in sorted(set(re.findall(r"\nex:(ST\w*?_\w+) a backlog:Story", t))):
        i, j = blk(t, s2); b = t[i:j]
        m = re.search(r"backlog:hasPriorityScore ex:Score(\d+[a-z]?)_%s\b" % s2, b)
        if not m or "backlog:hasState backlog:Done" in b or "backlog:hasState backlog:Cancelled" in b: continue
        kk = m.group(1)
        if ("\nex:Score%s_%s a" % (kk, s2)) not in t: continue
        k0 = t.index("\nex:Score%s_%s a" % (kk, s2)) + 1; r0 = t[k0:t.find("\nex:", k0 + 1)]
        q = re.search(r"business value (\d+) \+ time criticality (\d+) \+ risk reduction (\d+)\) / job size ([\d.]+) h", r0)
        if not q: continue
        nk = (kk[:-1] + chr(ord(kk[-1]) + 1)) if kk[-1].isalpha() else str(int(kk) + 1); nid = "Score%s_%s" % (nk, s2)
        if ("ex:" + nid + " a ") in t: continue
        bv, tc, rrr, size_ = int(q.group(1)), int(q.group(2)), int(q.group(3)), float(q.group(4)); extra = ""
        if s2 == "ST4_Items2": rrr += 5; extra = " Risk reduction raised by 5: the repair task TK4_Items_A3 sits in this story and blocks the engine build of every paper."
        val = (bv + tc + rrr) / size_
        t = t[:i] + b.replace(m.group(0), "backlog:hasPriorityScore ex:" + nid, 1) + t[j:]
        add.append('ex:%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%sZ"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (nid, val, now, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. RE-RUN on %s UTC after the repair entered the backlog (TK4_Items_A3).%s" % (bv, tc, rrr, size_, val, now, extra))))
    add.append("ex:Lineage4 backlog:hasAuditNote %s .\n" % W.lit("RANKING %s UTC after the repair TK4_Items_A3 entered: 1 TK4_Items_A3 (set A on the design plan; ST4_Items2 raised), 2 TK4_Engine5 control (the engine is built; its verdict follows), 3 TK4_Items_B2 and its control (Done after the engine builds the merged lists), 4 ST4_Papers (needs the engine and the items), the make-up last." % now))
    out = W.write_new(src, t + "\n" + "".join(add), "Exam change: the executor's report on TK4_Items_B2 controlled (true; not Done), finding on the cause (set A without the design plan), the counting ruling, the repair task TK4_Items_A3 and its control Ready and ranked first, scores re-run.")
    print(os.path.basename(out))
main()
